use crate::item_lookup::item_key;
use crate::item_tooltip::ItemTooltip;
use crate::maplestory_market::Market;
use crate::market_prices::DealLine;
use crate::osms_items::{ItemFacts, ItemSet, ScrollTier};
use crate::panel::{GameWindow, ScreenRect, Size, clear_of};
use crate::player_shop::{ListedPrice, ShopHover, ShopList, ShopReading, ShopRow};
use serde::Serialize;

/// The Deal Finder, as the panel shows it.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DealFinderView {
    /// The player has it on.
    pub on: bool,
    /// The Deal Line's name; `None` with nothing to judge against.
    pub deal_line: Option<String>,
    /// The Deal Line is one of maplestory.market's figures: the panel credits it.
    pub from_market: bool,
    /// What the Settings window offers as the Deal Line: maplestory.market's figures while
    /// they are on, then the player's Market Lines.
    pub choices: Vec<DealLineChoice>,
    /// "Market prices from maplestory.market" is on.
    pub market_prices: bool,
    /// How far below the Deal Line a price must be to be a deal, in percent.
    pub margin_percent: u32,
    /// A Player Shop's listings were found in the latest capture.
    pub shop_found: bool,
}

/// Something the Deal Line may be, as the Settings window offers it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DealLineChoice {
    /// What [`crate::Minerva::choose_deal_line`] takes for it.
    pub id: String,
    pub name: String,
    /// It is the Deal Line.
    pub chosen: bool,
}

/// One listing's Deal Badge, level with it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DealBadge {
    /// Which listing it is, counted from the top of those not sold out: what a click on it
    /// names ([`crate::Minerva::open_deal_item`]).
    pub row: u32,
    /// Its listing's top, from the top of the badges' window, and its height (physical px).
    pub top: u32,
    pub height: u32,
    /// Its listing is covered now, so its verdict is what was read there before (or "?"
    /// with nothing read there before).
    pub covered: bool,
    /// Its item's card shows, opened from it: the badge stays pressed.
    pub open: bool,
    #[serde(flatten)]
    pub verdict: Verdict,
}

/// What a Deal Badge says.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(tag = "verdict", rename_all = "camelCase", rename_all_fields = "camelCase")]
pub enum Verdict {
    /// One item costs at least the Deal Margin less than the Deal Line's price for it:
    /// `percent` off it (negative: below), rounded, the line's price, and how good a deal
    /// that is.
    Deal { item: DealItem, listed: ListedPrice, percent: i32, line_mesos: u64, grade: DealGrade },
    /// It doesn't: at or above the Deal Line's price, or below it by less than the Deal
    /// Margin.
    NoDeal { item: DealItem, listed: ListedPrice, percent: i32, line_mesos: u64 },
    /// The Deal Line has no price for the item.
    NoPrice { item: DealItem, listed: ListedPrice },
    /// The listing's name or price couldn't be read, or the name isn't one item's.
    Unknown,
}

/// How good a deal is, by how far below the Deal Line it is, graded as the game grades its
/// items: a good one under [`GREAT_BELOW`]%, a great one under [`STEAL_BELOW`]%, a steal past it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum DealGrade {
    Good,
    Great,
    Steal,
}

/// A deal this many percent below the Deal Line, or more, is great...
pub const GREAT_BELOW: i32 = 20;
/// ...and this many, or more, a steal.
pub const STEAL_BELOW: i32 = 40;

/// The item a listing sells, as OSMS's item files have it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DealItem {
    /// The game's item ID, 8 digits.
    pub id: String,
    pub name: String,
    /// A throwing star or a bullet: its listing's number is how many the set holds, and its
    /// price is the set's.
    pub rechargeable: bool,
}

/// The Deal Badges' window, while it shows.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DealBadges {
    pub placement: ScreenRect,
    pub badges: Vec<DealBadge>,
}

/// The Deal Finder: whether it is on, and the latest shop read.
#[derive(Default)]
pub(crate) struct DealFinder {
    pub on: bool,
    /// The listings in the latest capture; `None` while no shop was found, or it is off.
    shop: Option<ShopList>,
    /// The items each listing in `shop` is, as they were last judged: what a click on its
    /// badge opens.
    items: Vec<Option<Vec<u32>>>,
    /// The listings last read whole, each where it is, while the list stays at `seen_at`
    /// (its left edge on screen) and nothing read since says it changed: what a covered
    /// listing's badge says.
    seen: Vec<ShopRow>,
    seen_at: Option<i32>,
    /// The listings an Item Tooltip named, while `seen` stands.
    named: Vec<Named>,
    /// The pointer on the list in the latest capture, and the tooltip by it.
    hover: Option<ShopHover>,
    /// The Deal Badges' window's size, in physical px for the current display: its width
    /// counts, as its height follows the shop's list.
    pub size: Size,
}

/// A listing whose name the game cut short, named by the Item Tooltip by the pointer on it.
struct Named {
    /// Its slot's top on screen.
    top: i32,
    /// Its name as read there, cut short.
    cut: String,
    /// The tooltip's name as read.
    tooltip: String,
}

/// Two listings whose tops are this close (physical px) are in one slot.
const SAME_SLOT: i32 = 3;

fn same_slot(a: &ShopRow, b: &ShopRow) -> bool {
    (a.area.y - b.area.y).abs() <= SAME_SLOT
}

/// Whether `row` was read whole: its name and its price.
fn whole(row: &ShopRow) -> bool {
    !row.covered && row.name.is_some() && row.price.is_some()
}

/// The badges sit this far left of the shop's window (physical px).
const SHOP_GAP: i32 = 6;
/// The shop's window reaches this far left of its item list's picture column, and this far
/// right of it (physical px), at the samples' UI Size: as much farther at a larger one (ADR
/// 0020).
const SHOP_LEFT_OF_LIST: f32 = 8.0;
const SHOP_RIGHT_OF_LIST: f32 = 809.0;

/// How far the shop's window reaches left and right of `shop`'s list (physical px).
fn shop_reach(shop: &ShopList) -> (i32, i32) {
    let size = shop.ui_size();
    ((SHOP_LEFT_OF_LIST * size).round() as i32, (SHOP_RIGHT_OF_LIST * size).round() as i32)
}

impl DealFinder {
    /// Turn it on or off. Off, it forgets the shop it read.
    pub fn toggle(&mut self) {
        self.on = !self.on;
        if !self.on {
            self.shop = None;
            self.items.clear();
            self.forget();
            self.seen_at = None;
            self.hover = None;
        }
    }

    /// Forget what was read before, and the names tooltips gave it.
    fn forget(&mut self) {
        self.seen.clear();
        self.named.clear();
    }

    /// What a capture read as; ignored while it is off (a capture taken before it was
    /// turned off). The listings read whole are remembered where they are. The list has
    /// changed (scrolled, or a listing bought or sold out) when one of them reads otherwise
    /// than what was read there before, or a listing read before is gone and not covered:
    /// then nothing read before is kept, nor the names tooltips gave it. A listing whose name
    /// is cut short is named by the Item Tooltip by the pointer on its slot, if the tooltip's
    /// name starts as its does. A listing read again with no tier (its picture under the
    /// pointer) keeps the tier read there before.
    pub fn read(&mut self, reading: ShopReading) {
        if !self.on {
            return;
        }
        if let Some(list) = &reading.shop {
            if self.seen_at != Some(list.area.x) {
                self.forget();
                self.seen_at = Some(list.area.x);
            }
            let otherwise = list.rows.iter().filter(|row| whole(row)).any(|row| {
                self.seen.iter().any(|seen| same_slot(seen, row) && (seen.name != row.name || seen.price != row.price))
            });
            let gone = self.seen.iter().any(|seen| !list.rows.iter().any(|row| same_slot(row, seen)));
            if otherwise || gone {
                self.forget();
            }
            for row in list.rows.iter().filter(|row| whole(row)) {
                match self.seen.iter_mut().find(|seen| same_slot(seen, row)) {
                    // The tier read before stands while the pointer covers the picture.
                    Some(seen) => *seen = ShopRow { tier: row.tier.or(seen.tier), ..row.clone() },
                    None => self.seen.push(row.clone()),
                }
            }
            if let Some(hover) = &reading.hover {
                self.name_hovered(list, hover);
            }
        }
        self.shop = reading.shop;
        self.hover = reading.hover;
    }

    /// Name the listing whose slot the pointer is on by the tooltip by it, if the name read
    /// there (now, or before while it is covered) is cut short and the tooltip's starts so.
    fn name_hovered(&mut self, list: &ShopList, hover: &ShopHover) {
        let ItemTooltip::Found { name: Some(tooltip), .. } = &hover.tooltip else { return };
        let Some(row) = list.rows.iter().find(|row| on_slot(list, row, hover)) else { return };
        let seen = self.seen.iter().find(|seen| same_slot(seen, row));
        let read = if row.covered { seen.and_then(|seen| seen.name.as_ref()) } else { row.name.as_ref() };
        let Some(cut) = read.filter(|read| cut_start(read).is_some()).cloned() else { return };
        if !starts_as(tooltip, &cut) {
            return;
        }
        self.named.retain(|named| (named.top - row.area.y).abs() > SAME_SLOT);
        self.named.push(Named { top: row.area.y, cut, tooltip: tooltip.clone() });
    }

    pub fn shop(&self) -> Option<&ShopList> {
        self.shop.as_ref()
    }

    /// Where the shop's window is on screen, across, and its list's listings, down; `None`
    /// while no shop was found.
    pub fn shop_window(&self) -> Option<ScreenRect> {
        let shop = self.shop.as_ref()?;
        let ((left, right), list) = (shop_reach(shop), shop.area);
        Some(ScreenRect { x: list.x - left, width: (right + left) as u32, ..list })
    }

    /// The items the listing `row`'s badge is about, if it names one.
    pub fn row_items(&self, row: u32) -> Option<Vec<u32>> {
        self.items.get(row as usize).cloned().flatten()
    }

    /// Each listing's badge, judged against `line` (maplestory.market's figures from `market`)
    /// with the Deal Margin `margin_percent`, its items from `items` (none yet: every badge is
    /// "?"); tops from `top`, the badges' window's top on screen.
    /// `opened` is the badge (on screen) the Item Card showing opened from, with its items.
    pub fn badges(
        &mut self,
        items: Option<&ItemSet>,
        line: Option<DealLine>,
        market: &Market,
        margin_percent: u32,
        top: i32,
        opened: Option<(ScreenRect, &[u32])>,
    ) -> Vec<DealBadge> {
        let Some(shop) = &self.shop else {
            self.items.clear();
            return Vec::new();
        };
        let mut judged = Vec::with_capacity(shop.rows.len());
        let badges = shop
            .rows
            .iter()
            .enumerate()
            .map(|(row, shown)| {
                // Covered, what was read there before; or so under the pointer, where its name
                // reads as before and the tooltip by the pointer hides its price.
                let in_slot = self.seen.iter().find(|seen| same_slot(seen, shown));
                let hidden = shown.price.is_none()
                    && shown.name.is_some()
                    && in_slot.is_some_and(|seen| seen.name == shown.name)
                    && self.hover.as_ref().is_some_and(|hover| on_slot(shop, shown, hover));
                let seen = in_slot.filter(|_| shown.covered || hidden);
                let listing = seen.unwrap_or(shown);
                // Its picture's tier; with the pointer on the picture, the one read there before.
                let tier = listing.tier.or_else(|| in_slot.filter(|seen| seen.name == listing.name).and_then(|seen| seen.tier));
                let named = items.zip(listing.name.as_deref()).and_then(|(items, name)| {
                    item_named(items, name).or_else(|| {
                        let top = shown.area.y;
                        let by_picture = tier.and_then(|tier| picture_named(items, name, tier));
                        let by_tooltip = self
                            .named
                            .iter()
                            .find(|named| (named.top - top).abs() <= SAME_SLOT && named.cut == name)
                            .and_then(|named| tooltip_named(items, &named.tooltip, name));
                        // Naming another item than the picture does, or a scroll of another tier,
                        // one of them was misread.
                        let other_tier = by_tooltip.as_ref().is_some_and(|(item, _)| tier.zip(item.tier).is_some_and(|(a, b)| a != b));
                        match (by_picture, by_tooltip) {
                            _ if other_tier => None,
                            (Some((item, ids)), Some((_, tooltip_ids))) => (ids == tooltip_ids).then_some((item, ids)),
                            (picture, tooltip) => picture.or(tooltip),
                        }
                    })
                });
                let ids = named.as_ref().map(|(_, ids)| ids.clone());
                let open = opened.is_some_and(|(badge, opened)| badge.y == shown.area.y && ids.as_deref() == Some(opened));
                judged.push(ids);
                let verdict = match (named, listing.price) {
                    (Some((item, ids)), Some(listed)) => {
                        let item = DealItem { id: item_id(ids[0]), name: item.name.clone(), rechargeable: item.rechargeable };
                        let price = match line {
                            Some(DealLine::Line(line)) => line.prices.get(&item.id).map(|price| price.mesos),
                            Some(DealLine::Source(source)) => market.price(source, &item.id),
                            None => None,
                        };
                        match price {
                            Some(mesos) => judge(item, listed, mesos, margin_percent),
                            None => Verdict::NoPrice { item, listed },
                        }
                    }
                    _ => Verdict::Unknown,
                };
                DealBadge {
                    row: row as u32,
                    top: (shown.area.y - top).max(0) as u32,
                    height: shown.area.height,
                    covered: shown.covered || seen.is_some(),
                    open,
                    verdict,
                }
            })
            .collect();
        self.items = judged;
        badges
    }

    /// Where the badges' window goes over `game`: `width` wide, as tall as the shop's list,
    /// just left of the shop's window, or right of it with no room on the left; kept inside
    /// the client area and off `avoid` (the captured regions). `None` while no shop was
    /// found.
    pub fn placement(&self, game: &GameWindow, avoid: &[ScreenRect]) -> Option<ScreenRect> {
        let shop = self.shop.as_ref()?;
        let (list, span) = (shop.area, shop.span());
        let client = game.client;
        let width = self.size.width.min(client.width);
        let (shop_left, shop_right) = shop_reach(shop);
        let left = list.x - shop_left - SHOP_GAP - width as i32;
        let x = if left >= client.x { left } else { list.x + shop_right + SHOP_GAP };
        let strip = ScreenRect { x, y: span.y, width, height: span.height.min(client.height) };
        Some(clear_of(strip, avoid, client))
    }
}

/// The verdict on `listed` for `item`, against `line_mesos` on the Deal Line.
fn judge(item: DealItem, listed: ListedPrice, line_mesos: u64, margin_percent: u32) -> Verdict {
    // The price of one; of a throwing star's or a bullet's set, the listing's.
    let each = if item.rechargeable { listed.mesos as f64 } else { listed.mesos as f64 / listed.quantity as f64 };
    let line = line_mesos as f64;
    let percent = if line > 0.0 { ((each - line) / line * 100.0).round() as i32 } else { 0 };
    let deal = each < line && each <= line * (1.0 - f64::from(margin_percent) / 100.0);
    if deal {
        let grade = match -percent {
            below if below >= STEAL_BELOW => DealGrade::Steal,
            below if below >= GREAT_BELOW => DealGrade::Great,
            _ => DealGrade::Good,
        };
        Verdict::Deal { item, listed, percent, line_mesos, grade }
    } else {
        Verdict::NoDeal { item, listed, percent, line_mesos }
    }
}

/// The item a listing's name read as `read` is, with the items that look alike (its name,
/// kind and shop price; the first keeps the market prices): the item of that name, but for
/// the letters the recogniser confuses; or, for a name cut short ("Pet Equip Speed Scroll:
/// L..."), the one item whose name starts so. `None` when no item, or several that don't
/// look alike, have it.
fn item_named<'a>(items: &'a ItemSet, read: &str) -> Option<(&'a ItemFacts, Vec<u32>)> {
    let found = match cut_start(read) {
        Some(start) => items.starting_with(start),
        None => items.named(read),
    };
    alike(found)
}

/// The item an Item Tooltip's name read as `tooltip` is, for the listing whose name the game
/// cut short as `cut`: as [`item_named`] has a whole name, when its name starts as `cut`
/// does.
fn tooltip_named<'a>(items: &'a ItemSet, tooltip: &str, cut: &str) -> Option<(&'a ItemFacts, Vec<u32>)> {
    let (item, ids) = alike(items.named(tooltip))?;
    starts_as(&item.name, cut).then_some((item, ids))
}

/// The scroll a listing whose name the game cut short as `cut` is, by the tier its picture
/// shows: when every item whose name starts so is a scroll, the one name of that tier among
/// them, as [`item_named`] has a whole name. `None` when an item that isn't a scroll starts
/// so too, or no name or several are of that tier.
fn picture_named<'a>(items: &'a ItemSet, cut: &str, tier: ScrollTier) -> Option<(&'a ItemFacts, Vec<u32>)> {
    let names = items.names_starting_with(cut_start(cut)?);
    if names.iter().flatten().any(|item| item.tier.is_none()) {
        return None;
    }
    let mut of_tier = names.into_iter().filter(|name| name.iter().all(|item| item.tier == Some(tier)));
    match (of_tier.next(), of_tier.next()) {
        (Some(name), None) => alike(name),
        _ => None,
    }
}

/// The first of `found`, with them all, when they look alike (their kinds and shop prices).
fn alike(found: Vec<&ItemFacts>) -> Option<(&ItemFacts, Vec<u32>)> {
    let first = *found.first()?;
    let alike = found.iter().all(|item| item.kind == first.kind && item.shop == first.shop);
    alike.then(|| (first, found.iter().map(|item| item.id).collect()))
}

/// Where a name the game cut short ("Pet Equip Speed Scroll: L...") starts; `None` for a
/// whole one.
fn cut_start(read: &str) -> Option<&str> {
    let trimmed = read.trim_end_matches(['.', '…', ' ']);
    (trimmed.len() < read.trim_end().len()).then_some(trimmed)
}

/// Whether `name` starts as `cut`, a name the game cut short, does: compared as item names
/// are.
fn starts_as(name: &str, cut: &str) -> bool {
    let start = item_key(cut_start(cut).unwrap_or(cut));
    !start.is_empty() && item_key(name).starts_with(&start)
}

/// Whether `hover`'s pointer is on `row`'s slot in `list`: its band, across the list's
/// width, the pictures' column included.
fn on_slot(list: &ShopList, row: &ShopRow, hover: &ShopHover) -> bool {
    let slot = ScreenRect { x: list.area.x, width: list.area.width, ..row.area };
    slot.holds(hover.pointer)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn item() -> DealItem {
        DealItem { id: "04020000".into(), name: "Garnet Ore".into(), rechargeable: false }
    }

    fn verdict(quantity: u64, mesos: u64, line: u64, margin: u32) -> (bool, i32) {
        match judge(item(), ListedPrice { quantity, mesos }, line, margin) {
            Verdict::Deal { percent, .. } => (true, percent),
            Verdict::NoDeal { percent, .. } => (false, percent),
            _ => unreachable!(),
        }
    }

    #[test]
    fn a_deal_is_one_item_below_the_line_by_the_margin() {
        assert_eq!(verdict(1, 999, 1_000, 0), (true, 0));
        assert_eq!(verdict(1, 1_000, 1_000, 0), (false, 0));
        assert_eq!(verdict(10, 6_800, 1_000, 0), (true, -32));
        assert_eq!(verdict(1, 950, 1_000, 10), (false, -5));
        assert_eq!(verdict(1, 900, 1_000, 10), (true, -10));
        assert_eq!(verdict(1, 1_120, 1_000, 0), (false, 12));
    }
}

//! Every Player Shop sample, fed through the core's public inputs as a Deal Finder capture,
//! shows a Deal Badge for each listing not sold out, about the item and price the sample's
//! readings say, or a "?" badge: never another item, never another price (ADR 0014).
//!
//! - Each sample is a frame cropped to a shop's item list, as a Bug Report's
//!   `crops/player-shop-<ms>.png` is, so no seller's name, shop title or chat is committed;
//!   beside it, `<name>.json` lists its listings not sold out, top to bottom, each with the
//!   item's name as the game shows it ("…" and all, for a name it cuts short), the quantity
//!   and the mesos; or `{ "covered": true }` for one the pointer or the game's tooltip
//!   covers. Read on its own, a covered listing's badge says it is covered, or it has none:
//!   with no capture before, a slot the tooltip hides wholly isn't known to hold a listing.
//!   A listing whose name the game cut short so that it starts several items' names also
//!   says `"named"`: the item it is, as the Item Tooltip hovered over it names it. Its badge
//!   is "?" until it is hovered, unless its picture tells it.
//! - A scroll's listing whose name the game cut short says its `"tier"` too, as its picture
//!   shows it (#140), and only such a listing (a whole name names itself). In the made-up
//!   world every scroll whose name the game cut short starts four scrolls' names, one of each
//!   tier: only its picture tells which it is, so its badge names it unhovered.
//! - A hovered sample, `<name>@<x>,<y>.png`, is a frame of `<name>.png`'s shop with the
//!   pointer at (x, y) on a listing and the game's Item Tooltip by it, cut as far right as
//!   the tooltip's name line and past its edge, the shop's chat window painted out but for
//!   that line, and the chat showing through the tooltip painted its fill. It is fed after
//!   `<name>.png`, as the player sees a shop and then hovers a listing: its `"named"`
//!   listing's badge is that item's, or "?", whether the tooltip covers it or not.
//! - Each frame is fed as the game's client area at the screen's origin, as it is and as
//!   the darker colours of live captures (`prep.rs`), to a core of its own.
//! - Each is fed again at the other UI Sizes in [`OTHER_UI_SIZES`], scaled smoothly as the game
//!   draws its UI larger or smaller (ADR 0020): there a listing may read as unreadable, never as
//!   another item or price, and its badge sits level with it.

mod common;

use common::FakeSource;
use common::items::{ItemWorld, etc, item_world, scroll};
use minerva_core::bug_report::{self, Event};
use minerva_core::{
    DealBadge, Frame, ListedPrice, Minerva, PanelState, ReportAbout, ScreenPoint, Settings, ShopCapture, Size,
    Verdict,
};
use image::imageops::{self};
use image::{Rgba, RgbaImage};
use serde::Deserialize;
use std::collections::HashMap;

/// A listing's band is this wide at the UI Size most samples were taken at.
const SAMPLES_BAND_W: f32 = 253.0;
/// The UI Sizes every sample is also read at, next to the samples': #130's (a band 162 px
/// wide), and two larger.
const OTHER_UI_SIZES: [f32; 3] = [0.64, 1.5, 1.8];

/// One listing as a sample's readings write it: read, or covered; and the item an Item
/// Tooltip names it as, for one whose name the game cut short so that it could be several.
#[derive(Debug, Clone, Deserialize)]
#[serde(untagged)]
enum Listing {
    Read {
        name: String,
        quantity: u64,
        mesos: u64,
        #[serde(default)]
        tier: Option<String>,
        #[serde(default)]
        named: Option<String>,
    },
    Covered {
        covered: bool,
        #[serde(default)]
        named: Option<String>,
    },
}

impl Listing {
    fn named(&self) -> Option<&str> {
        match self {
            Listing::Read { named, .. } | Listing::Covered { named, .. } => named.as_deref(),
        }
    }
}

struct Sample {
    file: String,
    listings: Vec<Listing>,
    /// A hovered sample's pointer, in the frame.
    pointer: Option<ScreenPoint>,
    /// The sample of the same shop a hovered sample is fed after.
    partner: Option<String>,
}

fn samples() -> Vec<Sample> {
    let mut files: Vec<String> = std::fs::read_dir(common::samples_in("player-shop"))
        .expect("samples/player-shop")
        .map(|entry| entry.expect("dir entry").file_name().to_string_lossy().to_string())
        .filter(|name| name.ends_with(".png"))
        .collect();
    files.sort();
    files
        .into_iter()
        .map(|file| {
            let readings = common::samples_in("player-shop").join(file.replace(".png", ".json"));
            let text = std::fs::read_to_string(&readings).unwrap_or_else(|e| panic!("{}: {e}", readings.display()));
            let listings: Vec<Listing> = serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", readings.display()));
            let written = listings.iter().all(|l| !matches!(l, Listing::Covered { covered: false, .. }));
            assert!(written, "{}: a listing is read, or `\"covered\": true`", readings.display());
            let tiers_cut = listings.iter().all(|l| !matches!(l, Listing::Read { name, tier: Some(_), .. } if cut_start(name).is_none()));
            assert!(tiers_cut, "{}: a `\"tier\"` only beside a name the game cut short", readings.display());
            let (pointer, partner) = match file.trim_end_matches(".png").split_once('@') {
                Some((name, at)) => {
                    let (x, y) = at.split_once(',').unwrap_or_else(|| panic!("{file}: <name>@<x>,<y>"));
                    let pointer = ScreenPoint { x: x.parse().expect("x"), y: y.parse().expect("y") };
                    (Some(pointer), Some(format!("{name}.png")))
                }
                None => (None, None),
            };
            Sample { file, listings, pointer, partner }
        })
        .collect()
}

/// The scroll tiers, as the readings write them.
const TIERS: [&str; 4] = ["Lesser", "Intermediate", "Greater", "Chaos"];

/// Where a listing's name the game cut short starts; `None` for a whole one.
fn cut_start(listing: &str) -> Option<&str> {
    listing.strip_suffix("...").or_else(|| listing.strip_suffix('…'))
}

/// The item a listing's name stands for: the name, or for one the game cut short, a
/// made-up name that starts as it does.
fn item_name(listing: &str) -> String {
    match cut_start(listing) {
        Some(start) => format!("{start}egs for Made Up"),
        None => listing.to_string(),
    }
}

/// The made-up scrolls each scroll listing whose name the game cut short could be, by where
/// its name starts: one of each tier (in [`TIERS`]' order), the item a listing of that tier
/// is `"named"` where one is.
fn families(samples: &[Sample]) -> HashMap<String, [String; 4]> {
    let mut named: HashMap<String, [Option<String>; 4]> = HashMap::new();
    for listing in samples.iter().flat_map(|s| &s.listings) {
        if let Listing::Read { name, tier: Some(tier), named: of, .. } = listing
            && let Some(start) = cut_start(name)
        {
            let family = named.entry(start.to_string()).or_default();
            if let Some(of) = of {
                family[tier_at(tier)] = Some(of.clone());
            }
        }
    }
    named
        .into_iter()
        .map(|(start, family)| {
            let scroll = |at: usize| family[at].clone().unwrap_or_else(|| format!("{start}egs for Made Up, {}", TIERS[at]));
            let family = std::array::from_fn(scroll);
            (start, family)
        })
        .collect()
}

/// Where `tier` is in [`TIERS`].
fn tier_at(tier: &str) -> usize {
    TIERS.iter().position(|&t| t == tier).unwrap_or_else(|| panic!("a tier: {tier:?}"))
}

/// The item a listing read as `name` names, unhovered: a scroll whose name the game cut short,
/// the one of its picture's tier; any other, its own, unless it could be several (`named`).
fn expected(families: &HashMap<String, [String; 4]>, name: &str, tier: Option<&str>, named: Option<&str>) -> Option<String> {
    match cut_start(name).and_then(|start| families.get(start)).zip(tier) {
        Some((family, tier)) => Some(family[tier_at(tier)].clone()),
        None => named.is_none().then(|| item_name(name)),
    }
}

/// The made-up world the samples are read in: its items, and the scrolls each scroll listing
/// whose name the game cut short could be ([`families`]; none in a world where no item is a
/// scroll).
struct World {
    items: ItemWorld,
    families: HashMap<String, [String; 4]>,
}

/// Made-up item data with an item of each listing's name, and the item each is named as: a
/// listing named so starts both items' names. With `scrolls`, a scroll's listing whose name the
/// game cut short starts the names of the four scrolls of its family instead ([`families`]), so
/// its picture names it; without, only its tooltip can.
fn world(samples: &[Sample], scrolls: bool) -> World {
    let families = if scrolls { families(samples) } else { HashMap::new() };
    let in_family: Vec<&String> = families.values().flatten().collect();
    let mut names: Vec<String> = samples
        .iter()
        .flat_map(|s| &s.listings)
        .flat_map(|l| {
            let read = match l {
                Listing::Read { name, .. } if cut_start(name).is_some_and(|start| families.contains_key(start)) => None,
                Listing::Read { name, .. } => Some(item_name(name)),
                Listing::Covered { .. } => None,
            };
            read.into_iter().chain(l.named().map(String::from))
        })
        .filter(|name| !in_family.contains(&name))
        .collect();
    names.sort();
    names.dedup();
    let mut items = item_world(Vec::new());
    for (n, name) in names.iter().enumerate() {
        items = items.with(etc(4_100_000 + n as u64, name).sells_for(10));
    }
    let mut starts: Vec<&String> = families.keys().collect();
    starts.sort();
    for (n, start) in starts.into_iter().enumerate() {
        for (at, name) in families[start].iter().enumerate() {
            items = items.with_scroll(scroll(2_040_000 + 4 * n as u64 + at as u64, name).of_tier(TIERS[at]));
        }
    }
    World { items, families }
}

/// A core over a 1920x1200 game window at the screen's origin, with `world`'s items in and the
/// Deal Finder on.
fn started(world: &World) -> Minerva {
    let mut minerva = Minerva::new(FakeSource::osms_offline().with_items(world.items.clone()));
    minerva.restore(Settings::default());
    minerva.on_game_window(Some(common::window_at_origin(1920, 1200)));
    minerva.set_deal_badges_size(Size { width: 160, height: 0 });
    minerva.tick(0);
    assert!(minerva.on_hotkey("ctrl+shift+d").is_none());
    minerva
}

fn image_of(file: &str) -> RgbaImage {
    image::open(common::samples_in("player-shop").join(file)).unwrap_or_else(|e| panic!("{file}: {e}")).to_rgba8()
}

/// The UI Size `img` shows, next to the samples': the widest its listings' bands run on a
/// listing's worth of rows, of the band's colour at any brightness (narrower where something
/// covers them), over the samples'.
fn sample_ui_size(img: &RgbaImage) -> f32 {
    let band = |p: &Rgba<u8>| {
        let k = p[2] as f32 / 223.0;
        (0.8..=1.1).contains(&k) && (p[0] as f32 - 202.0 * k).abs() <= 6.0 && (p[1] as f32 - 213.0 * k).abs() <= 6.0
    };
    let mut runs: HashMap<u32, usize> = HashMap::new();
    for y in 0..img.height() {
        let mut x = 0;
        while x < img.width() {
            let start = x;
            while x < img.width() && band(img.get_pixel(x, y)) {
                x += 1;
            }
            if x - start >= 100 {
                *runs.entry(x - start).or_default() += 1;
            }
            x = x.max(start + 1);
        }
    }
    let width = runs.into_iter().filter(|&(_, rows)| rows >= 10).map(|(width, _)| width).max().expect("a listing's band");
    width as f32 / SAMPLES_BAND_W
}

/// The captures `sample` is fed as, each image made a frame by `frame` at `factor` times its
/// size: a hovered sample's partner's first, then its own with the pointer on it.
fn captures(sample: &Sample, factor: f32, frame: impl Fn(&RgbaImage) -> Frame) -> Vec<ShopCapture> {
    let at = |v: i32| (v as f32 * factor).round() as i32;
    let pointer = sample.pointer.map(|p| ScreenPoint { x: at(p.x), y: at(p.y) });
    let capture = |file: &str, pointer| ShopCapture { frame: frame(&image_of(file)), origin: ScreenPoint { x: 0, y: 0 }, pointer };
    sample.partner.iter().map(|partner| capture(partner, None)).chain([capture(&sample.file, pointer)]).collect()
}

fn badges(state: &PanelState) -> Vec<DealBadge> {
    state.deal_badges.as_ref().map(|shown| shown.badges.clone()).unwrap_or_default()
}

/// What a badge says the listing is: its item's name and price; `None` for "?".
fn read(badge: &DealBadge) -> Option<(String, ListedPrice)> {
    match &badge.verdict {
        Verdict::Deal { item, listed, .. } | Verdict::NoDeal { item, listed, .. } | Verdict::NoPrice { item, listed } => {
            Some((item.name.clone(), *listed))
        }
        Verdict::Unknown => None,
    }
}

/// What a frame of a sample read as, against its readings.
struct Checked {
    /// Its listings read as unreadable.
    unreadable: usize,
    /// Of them, the hovered one.
    hovered_unreadable: usize,
    /// Where each badge of a listing not covered is on screen: its top and its height.
    places: Vec<(i32, u32)>,
}

/// Feed `captures` of `sample` to a core of its own, and check its badges after against the
/// sample's readings: what reads wrong goes in `wrong`, labelled `label`; `None` when the
/// badges aren't the readings' listings one for one.
fn check(world: &World, sample: &Sample, captures: Vec<ShopCapture>, label: &str, wrong: &mut Vec<String>) -> Option<Checked> {
    let mut minerva = started(world);
    let pointer = captures.last().and_then(|capture| capture.pointer);
    let mut state = None;
    for capture in captures {
        state = Some(minerva.on_player_shop_capture(capture).clone());
    }
    let state = state.expect("a capture");
    let window_top = state.deal_badges.as_ref().map_or(0, |shown| shown.placement.y);
    let badges = badges(&state);
    let mut checked = Checked { unreadable: 0, hovered_unreadable: 0, places: Vec::new() };
    // A hovered listing reads covered or not, as far as the tooltip hides it: it is set
    // aside, and its badge is the one level with the pointer.
    let hovered = sample.listings.iter().position(|l| l.named().is_some()).zip(pointer);
    let (listings, badges): (Vec<&Listing>, Vec<&DealBadge>) = match hovered {
        Some((at, pointer)) => {
            let named = sample.listings[at].named().expect("named");
            let level = |b: &&DealBadge| (0..b.height as i32).contains(&(pointer.y - window_top - b.top as i32));
            match badges.iter().find(level).and_then(read) {
                Some((read, _)) if read == named => {}
                None => {
                    checked.unreadable += 1;
                    checked.hovered_unreadable += 1;
                }
                Some(read) => wrong.push(format!("{label}: {read:?}, not {named:?}")),
            }
            let listings = sample.listings.iter().enumerate().filter(|&(i, _)| i != at).map(|(_, l)| l).collect();
            (listings, badges.iter().filter(|b| !level(b)).collect())
        }
        None => (sample.listings.iter().collect(), badges.iter().collect()),
    };
    let (covered, uncovered): (Vec<&DealBadge>, Vec<&DealBadge>) = badges.into_iter().partition(|b| b.covered);
    let covers = listings.iter().filter(|l| matches!(l, Listing::Covered { .. })).count();
    let reads: Vec<(Option<String>, ListedPrice)> = listings
        .iter()
        .filter_map(|l| match l {
            Listing::Read { name, quantity, mesos, tier, .. } => {
                let price = ListedPrice { quantity: *quantity, mesos: *mesos };
                Some((expected(&world.families, name, tier.as_deref(), l.named()), price))
            }
            Listing::Covered { .. } => None,
        })
        .collect();
    if uncovered.len() != reads.len() || covered.len() > covers {
        let found = format!("{} listings found and {} covered", uncovered.len(), covered.len());
        wrong.push(format!("{label}: {found}, not {} and up to {covers}", reads.len()));
        return None;
    }
    for (badge, (named, price)) in uncovered.into_iter().zip(reads) {
        checked.places.push((window_top + badge.top as i32, badge.height));
        // Not hovered, a name that starts several items' is "?", unless its picture tells it.
        let expected = named.map(|named| (named, price));
        match (read(badge), expected) {
            (Some(read), Some(expected)) if read == expected => {}
            (None, Some(_)) => checked.unreadable += 1,
            (None, None) => {}
            (Some(read), expected) => wrong.push(format!("{label}: {read:?}, not {expected:?}")),
        }
    }
    Some(checked)
}

#[test]
fn every_samples_listings_read_as_its_readings_say_or_as_unreadable_never_wrong() {
    let samples = samples();
    assert!(samples.len() >= 3, "expected the Player Shop samples, found {}", samples.len());
    let world = world(&samples, true);
    let mut wrong = Vec::new();
    let mut unreadable = 0;
    for sample in &samples {
        for brightness in [1.0, 0.935] {
            let label = format!("{} ×{brightness}", sample.file);
            let captures = captures(sample, 1.0, |img| common::dimmed(img, brightness));
            if let Some(checked) = check(&world, sample, captures, &label, &mut wrong) {
                unreadable += checked.unreadable;
            }
        }
    }
    assert!(wrong.is_empty(), "wrong readings:\n{}", wrong.join("\n"));
    // The samples were all read whole when they were added: a reader that reads less of them
    // has got worse, though it says nothing wrong.
    assert_eq!(unreadable, 0, "listings now unreadable");
}

#[test]
fn every_samples_listings_read_at_other_ui_sizes_as_its_readings_say_or_as_unreadable_never_wrong() {
    let samples = samples();
    let world = world(&samples, true);
    let mut wrong = Vec::new();
    let mut misplaced = Vec::new();
    for sample in &samples {
        let img = image_of(&sample.file);
        let own = sample_ui_size(&img);
        let at_own = check(&world, sample, captures(sample, 1.0, |img| common::dimmed(img, 1.0)), &sample.file, &mut wrong);
        for size in OTHER_UI_SIZES {
            let factor = size / own;
            if (factor - 1.0).abs() < 0.05 {
                continue;
            }
            for brightness in [1.0, 0.935] {
                let label = format!("{} at ×{size} ×{brightness}", sample.file);
                let captures = captures(sample, factor, |img| common::dimmed(&common::scaled(img, factor), brightness));
                let Some(checked) = check(&world, sample, captures, &label, &mut wrong) else {
                    continue;
                };
                let Some(at_own) = &at_own else { continue };
                // Within 2 px, and a px at the sample's own size: read at another UI Size than
                // the samples' itself, its own badges are placed to a px there.
                let slack = 2 + if (own - 1.0).abs() < 0.02 { 0 } else { factor.ceil() as u32 };
                for (&(top, height), &(own_top, own_height)) in checked.places.iter().zip(&at_own.places) {
                    let expected = ((own_top as f32 * factor).round() as i32, (own_height as f32 * factor).round() as u32);
                    if top.abs_diff(expected.0) > slack || height.abs_diff(expected.1) > slack {
                        misplaced.push(format!("{label}: a badge at {top}, {height} px tall, not {}, {}", expected.0, expected.1));
                    }
                }
            }
        }
    }
    assert!(wrong.is_empty(), "wrong readings:\n{}", wrong.join("\n"));
    assert!(misplaced.is_empty(), "badges not level with their listings:\n{}", misplaced.join("\n"));
}

/// Bands narrower or wider than at any UI Size the reader takes (ADR 0020), and a stack of the
/// band's colour with no listing on it, are no shop.
