        }
    }

    #[test]
    fn packed_iou_matches_the_slow_one() {
        let a = bm(&["..##.", ".#..#", ".####", ".#..#", ".#..#"]);
        let cases = [
            bm(&["..##.", ".#..#", ".####", ".#..#", ".#..#"]),
            bm(&[".##..", "#..#.", "####.", "#..#.", "#..#."]),
            bm(&["###", "#.#", "###", "#.#"]),
            bm(&["#####", "#...#", "#...#", "#####", "....."]),
        ];
        for b in &cases {
            let (pa, pb) = (pack(&a).unwrap(), pack(b).unwrap());
            let (fast, slow) = (iou_shifted_packed(&pa, &pb), iou_shifted(&a, b));
